 scanf("%d",&N);
 scanf("%d",&A);
 MAYOR=A;
 MENOR=A;
 for(I=1;I<N;I++){
  scanf("%d",&A);
  if(A>MAYOR) MAYOR=A;
  if(A<MENOR) MENOR=A;
 }
 printf("Mayor: %d Menor: %d\n",MAYOR,MENOR);
 return 0;
}

